def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    seen = set()

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue

            comp = set()
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                comp.add((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        q = (y + dy, x + dx)
                        if (dy or dx) and 0 <= q[0] < h and 0 <= q[1] < w:
                            if grid[q[0]][q[1]] == color and q not in seen:
                                seen.add(q)
                                stack.append(q)

            if len(comp) < 2:
                continue
            endpoints = []
            for y, x in comp:
                neighbors = [(y + dy, x + dx)
                             for dy in (-1, 0, 1) for dx in (-1, 0, 1)
                             if (dy or dx) and (y + dy, x + dx) in comp]
                if len(neighbors) == 1:
                    endpoints.append((y, x, neighbors[0]))
            if not endpoints:
                continue

            y, x, prev = max(endpoints, key=lambda p: (p[0], p[1]))
            dy, dx = y - prev[0], x - prev[1]
            ny, nx = y + dy, x + dx
            while 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == bg:
                out[ny][nx] = color
                ny += dy
                nx += dx

    return out
